import {APPAREL_VARIANTS} from './apparel-variants.mjs';
export async function apparelPhoto(request,url,env){if(url.pathname!=='/api/apparel/photo')return null;if(request.method!=='GET')return new Response('Method not allowed',{status:405});const colours=APPAREL_VARIANTS[url.searchParams.get('product')],index=Number(url.searchParams.get('colour')||0),side=url.searchParams.get('side')==='back'?'back':'front';if(!Number.isInteger(index)||!colours?.[index])return new Response('Photo unavailable',{status:404});return env.ASSETS.fetch(new Request(new URL(colours[index][side],url),request));}
